using Aethvirse.Combat;
using NUnit.Framework;
using UnityEditor;

namespace Aethvirse.Tests
{
    /// <summary>The greatsword combo asset (generated by CombatDataBuilder from the Godot data).</summary>
    public sealed class ComboGraphTests
    {
        const string ComboPath = "Assets/Data/Combat/Greatsword/GreatswordCombo.asset";
        static readonly string[] AllChains = { "L", "LL", "LLL", "LLLL", "LLLLL", "H", "LH", "LLH", "LLLH", "LLLLH" };
        ComboData _combo;

        [SetUp]
        public void SetUp()
        {
            _combo = AssetDatabase.LoadAssetAtPath<ComboData>(ComboPath);
            Assert.That(_combo, Is.Not.Null, $"missing {ComboPath}");
        }

        AttackData Chain(string inputs)
        {
            AttackData current = null;
            foreach (char c in inputs) current = _combo.ResolveNext(current, c == 'H');
            return current;
        }

        [Test]
        public void LightChain_HasFiveHits()
        {
            Assert.That(Chain("L").id, Is.EqualTo("light_1"));
            Assert.That(Chain("LLLLL").id, Is.EqualTo("light_5"));
        }

        [Test]
        public void Chain_RestartsAfterFinisher() => Assert.That(Chain("LLLLLL").id, Is.EqualTo("light_1"));

        [TestCase("H", "overhead_smash"), TestCase("LH", "rising_cleave"), TestCase("LLH", "whirlwind"),
         TestCase("LLLH", "ground_slam"), TestCase("LLLLH", "piercing_thrust")]
        public void Branches(string inputs, string id) => Assert.That(Chain(inputs).id, Is.EqualTo(id));

        [Test]
        public void AllAttacks_HaveSaneTimings()
        {
            foreach (string inputs in AllChains)
            {
                AttackData a = Chain(inputs);
                Assert.That(a.active, Is.GreaterThan(0f), a.id);
                Assert.That(a.comboWindow, Is.LessThanOrEqualTo(a.Total), $"{a.id} combo window inside attack");
                Assert.That(a.dodgeCancel, Is.LessThanOrEqualTo(a.Total), $"{a.id} dodge cancel inside attack");
                Assert.That(a.damageMultiplier, Is.GreaterThan(0f), a.id);
                Assert.That(a.hitboxOffset.z, Is.GreaterThanOrEqualTo(0f), $"{a.id} hitbox in front (+Z) or centred");
            }
        }
    }
}
